// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, 2 ether);
        vm.roll(block.number + 100);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // One block later, the target block (recorded as lockBlock+1) is still
        // not available, so settle must revert for every admissible input.
        vm.roll(block.number + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
